/**
 * Extracted helper to handle JSON response parsing with type checking
 * @param {Response} res - The fetch response object
 * @returns {Promise<any>} Parsed JSON or empty object if not JSON
 */
async function parseJsonResponse(res) {
    const contentType = (res.headers.get('content-type') || '').toLowerCase();
    if (contentType.includes('application/json')) {
        try {
            return await res.json();
        } catch (e) {
            // fall through to response used pre-OTC
        }
    }
    return {};
}

/**
 * Extracted helper to handle error throwing with HumanReadableError support
 * @param {Response} res - The fetch response object
 * @param {string} fallbackMessage - Fallback error message
 * @returns {Promise<never>} Throws appropriate error
 */
async function throwApiError(res, fallbackMessage) {
    const humanError = await HumanReadableError.fromApiResponse(res);
    if (humanError) {
        throw humanError;
    }
    throw new Error(fallbackMessage);
}

/**
 * Extracted helper to handle successful response processing
 * @param {Response} res - The fetch response object
 * @param {string} successType - Type of success handling ('json' or 'text')
 * @returns {Promise<any>} Parsed response data
 */
async function handleSuccessResponse(res, successType = 'json') {
    if (successType === 'text') {
        return res.text();
    }
    return res.json();
}

/**
 * Extracted helper to handle error response processing
 * @param {Response} res - The fetch response object
 * @param {string} fallbackMessage - Fallback error message
 * @returns {Promise<never>} Throws appropriate error
 */
async function handleErrorResponse(res, fallbackMessage) {
    const humanError = await HumanReadableError.fromApiResponse(res);
    if (humanError) {
        throw humanError;
    }
    throw new Error(fallbackMessage);
}

function setupGhostApi({siteUrl = window.location.origin, apiUrl, apiKey}) {
    const apiPath = 'members/api';

    function endpointFor({type, resource}) {
        if (type === 'members') {
            return `${siteUrl.replace(/\/$/, '')}/${apiPath}/${resource}/`;
        }
    }

    function contentEndpointFor({resource, params = {}}) {
        if (apiUrl && apiKey) {
            const searchParams = new URLSearchParams({
                ...params,
                key: apiKey
            });
            return `${apiUrl.replace(/\/$/, '')}/${resource}/?${searchParams.toString()}`;
        }
        return '';
    }

    function makeRequest({url, method = 'GET', headers = {}, credentials = undefined, body = undefined}) {
        const options = {
            method,
            headers,
            credentials,
            body
        };
        return fetch(url, options);
    }
    const api = {};

    api.site = {
        read() {
            const url = endpointFor({type: 'members', resource: 'site'});
            return makeRequest({
                url,
                method: 'GET',
                headers: {
                    'Content-Type': 'application/json'
                }
            }).then(function (res) {
                if (res.ok) {
                    return res.json();
                } else {
                    throw new Error('Failed to fetch site data');
                }
            });
        },

        newsletters() {
            const url = contentEndpointFor({resource: 'newsletters', params: {limit: 100}});
            return makeRequest({
                url,
                method: 'GET',
                headers: {
                    'Content-Type': 'application/json'
                }
            }).then(function (res) {
                if (res.ok) {
                    return res.json();
                } else {
                    throw new Error('Failed to fetch site data');
                }
            });
        },

        tiers() {
            const url = contentEndpointFor({resource: 'tiers', params: {limit: 100, include: 'monthly_price,yearly_price,benefits'}});
            return makeRequest({
                url,
                method: 'GET',
                headers: {
                    'Content-Type': 'application/json'
                }
