const copyImageToClipboard = async (ref: React.RefObject<HTMLDivElement>, setIsProcessing: React.Dispatch<React.SetStateAction<boolean>>) => {
    if (!ref.current || !navigator.clipboard || !('write' in navigator.clipboard) || typeof ClipboardItem === 'undefined') {
        toast.error('Clipboard API not supported in this browser');
        setIsProcessing(false);
        return;
    }

    setIsProcessing(true);
    await new Promise((resolve) => {
        requestAnimationFrame(() => {
            requestAnimationFrame(resolve);
        });
    });

    try {
        const canvas = await html2canvas(ref.current, {
            backgroundColor: 'transparent',
            scale: 2,
            logging: false,
            useCORS: true,
            allowTaint: true,
            imageTimeout: 0
        });

        let blob: Blob | null = null;
        await new Promise<void>((resolve, reject) => {
            canvas.toBlob((b) => {
                if (b) {
                    blob = b;
                    resolve();
                } else {
                    reject(new Error('Failed to create blob'));
                }
            }, 'image/png');
        });

        if (!blob) {
            throw new Error('Blob not created');
        }

        const clipboardItem = new ClipboardItem({'image/png': blob});
        await navigator.clipboard.write([clipboardItem]);
        toast.success('Image copied to clipboard');
    } catch {
        toast.error('Failed to copy image');
    } finally {
        setIsProcessing(false);
    }
};

