export default class KoenigLexicalEditor extends Component {
    @service ajax;
    @service feature;
    @service ghostPaths;
    @service koenig;
    @service membersUtils;
    @service search;
    @service session;
    @service settings;
    @service store;

    @inject config;

    offers = null;
    contentKey = null;
    defaultLinks = null;

    editorResource = this.koenig.resource;

    get pinturaJsUrl() {
        if (!this.settings.pintura) {
            return null;
        }
        return this.config.pintura?.js || this.settings.pinturaJsUrl;
    }

    get pinturaCSSUrl() {
        if (!this.settings.pintura) {
            return null;
        }
        return this.config.pintura?.css || this.settings.pinturaCssUrl;
    }

    get pinturaConfig() {
        const jsUrl = this.getImageEditorJSUrl();
        const cssUrl = this.getImageEditorCSSUrl();
        if (!jsUrl || !cssUrl) {
            return null;
        }
        return {
            jsUrl,
            cssUrl
        };
    }

    getImageEditorJSUrl() {
        let importUrl = this.pinturaJsUrl;

        if (!importUrl) {
            return null;
        }

        if (importUrl.startsWith('/')) {
            importUrl = window.location.origin + this.ghostPaths.adminRoot.replace(/\/$/, '') + importUrl;
        }
        return importUrl;
    }

    getImageEditorCSSUrl() {
        let cssImportUrl = this.pinturaCSSUrl;

        if (!cssImportUrl) {
            return null;
        }

        if (cssImportUrl.startsWith('/')) {
            cssImportUrl = window.location.origin + this.ghostPaths.adminRoot.replace(/\/$/, '') + cssImportUrl;
        }
        return cssImportUrl;
    }

    @action
    onError(error) {
        console.error(error); // eslint-disable-line

        if (this.config.sentry_dsn) {
            Sentry.captureException(error, {
                tags: {lexical: true},
                contexts: {
                    koenig: {
                        version: window['@tryghost/koenig-lexical']?.version
                    }
                }
            });
        }
    }

    @task({restartable: false})
    *fetchOffersTask() {
        if (this.offers) {
            return this.offers;
        }

        this.offers = yield this.store.query('offer', {filter: 'status:active+redemption_type:signup'});
        return this.offers;
    }

    @task({restartable: false})
    *fetchLabelsTask() {
        if (this.labels) {
            return this.labels;
        }

        this.labels = yield this.store.query('label', {limit: 'all', fields: 'id, name'});
        return this.labels;
    }

    ReactComponent = (props) => {
        const fetchEmbed = async (url, {type}) => {
            const oembedEndpoint = this.ghostPaths.url.api('oembed');
            const response = await this.ajax.request(oembedEndpoint, {
                data: {url, type}
            });
            return response;
        };

        const fetchAutocompleteLinks = async () => {
            const defaults = [
                {label: 'Homepage', value: window.location.origin + '/'},
                {label: 'Free signup', value: '#/portal/signup/free'}
            ];

            const memberLinks = this.renderMemberLinks();
            const donationLink = this.renderDonationLink();
            const recommendationLink = this.renderRecommendationLink();
            const offersLinks = await offerUrls.call(this);

            return [...defaults, ...memberLinks, ...donationLink, ...recommendationLink, ...offersLinks];
        };

        const fetchLabels = async () => {
            try {
                const labels = await this.fetchLabelsTask.perform();
                return labels.map(label => label.name);
            } catch (e) {
                if (didCancel(e)) {
                    return [];
                }
                throw e;
            }
        };

        const searchLinks = async (term) => {
            if (!term) {
                return this.getCachedDefaultLinks();
            }

            return this.performSearch(term);
        };

        const unsplashConfig = {
            defaultHeaders: {
                Authorization: `Client-ID 8672af113b0a8573edae3aa3713886265d9bb741d707f6c01a486cde8c278980`,
                'Accept-Version': 'v1',
                'Content-Type': 'application/json',
                'App-Pragma': 'no-cache',
                'X-Unsplash-Cache': true
            }
        };

        const checkStripeEnabled = () => {
            const hasDirectKeys = !!(this.settings.stripeSecretKey && this.settings.stripePublishableKey);
            const hasConnectKeys = !!(this.settings.stripeConnectSecretKey && this.settings.stripeConnectPublishableKey);

            if (this.config.stripeDirect) {
                return hasDirectKeys;
            }
            return hasDirectKeys || hasConnectKeys;
        };

        const defaultCardConfig = {
            unsplash: this.settings.unsplash ? unsplashConfig.defaultHeaders : null,
            tenor: this.config.tenor?.googleApiKey ? this.config.tenor : null,
            fetchAutocompleteLinks,
            fetchEmbed,
            fetchLabels,
            renderLabels: !this.session.user.isContributor,
            feature: {
                transistor: this.feature.transistor
            },
            deprecated: {
                headerV1: true
            },
            membersEnabled: this.settings.membersSignupAccess === 'all',
            searchLinks,
            siteTitle: this.settings.title,
            siteDescription: this.settings.description,
            siteUrl: this.config.getSiteUrl('/'),
            stripeEnabled: checkStripeEnabled()
        };

        const cardConfig = Object.assign({}, defaultCardConfig, props.cardConfig, {pinturaConfig: this.pinturaConfig});

        const useFileUpload = (type = 'image') => {
            const [progress, setProgress] = React.useState(0);
            const [isLoading, setLoading] = React.useState(false);
            const [errors, setErrors] = React.useState([]);
            const [filesNumber, setFilesNumber] = React.useState(0);

            const progressTracker = React.useRef(new Map());

            function updateProgress() {
                if (progressTracker.current.size === 0) {
                    setProgress(0);
                    return;
                }

                const totalProgress = Array.from(progressTracker.current.values()).reduce((sum, value) => sum + value, 0);
                setProgress(Math.round(totalProgress / progressTracker.current.size));
            }

            const defaultValidator = (file) => {
                if (type === 'file') {
                    return true;
                }

                const extensions = fileTypes[type].extensions;
                const [, extension] = (/(?:\.([^.]+))?$/).exec(file.name);

                if (!extensions) {
                    return true;
                }

                const extensionList = Array.isArray(extensions) ? extensions : extensions.split(',');
                const normalizedExtension = (extension || '').toLowerCase();

                if (!extension || extensionList.indexOf(normalizedExtension) === -1) {
                    const validExtensions = `.${extensionList.join(', .').toUpperCase()}`;
                    return `The file type you uploaded is not supported. Please use ${validExtensions}`;
                }

                return true;
            };

            const validate = (files = []) => {
                const validationResult = [];

                for (let i = 0; i < files.length; i += 1) {
                    const file = files[i];
                    const result = defaultValidator(file);
                    if (result !== true) {
                        validationResult.push({fileName: file.name, message: result});
                    }
                }

                return validationResult;
            };

            const _uploadFile = async (file, {formData = {}} = {}) => {
                progressTracker.current.set(file, 0);

                const fileFormData = new FormData();
                fileFormData.append('file', file, file.name);

                Object.keys(formData || {}).forEach((key) => {
                    fileFormData.append(key, formData[key]);
                });

                const url = `${ghostPaths().apiRoot}${fileTypes[type].endpoint}`;
                const requestMethod = fileTypes[type].requestMethod || 'post';

                try {
                    const response = await this.ajax[requestMethod](url, {
                        data: fileFormData,
                        processData: false,
                        contentType: false,
                        dataType: 'text',
                        xhr: this.createXhrWithProgress(file, updateProgress, progressTracker)
                    });

                    progressTracker.current.set(file, 100);
                    updateProgress();

                    return this.extractUploadResponse(response, type);
                } catch (error) {
                    return this.processUploadError(error, file);
                }
            };

            const upload = async (files = [], options = {}) => {
                setFilesNumber(files.length);
                setLoading(true);

                const validationResult = validate(files);

                if (validationResult.length) {
                    setErrors(validationResult);
                    setLoading(false);
                    setProgress(100);
                    return null;
                }

                const uploadPromises = files.map(file => _uploadFile(file, options));

                try {
                    const uploadResult = await Promise.all(uploadPromises);
                    setProgress(100);
                    progressTracker.current.clear();
                    setLoading(false);
                    setErrors([]);
                    return uploadResult;
                } catch (error) {
                    console.error(error); // eslint-disable-line no-console
                    setErrors([...errors, error]);
                    setLoading(false);
                    setProgress(100);
                    progressTracker.current.clear();
                    return null;
                }
            };

            return {progress, isLoading, upload, errors, filesNumber};
        };

        const KGEditorComponent = ({isInitInstance}) => {
            return (
                <div data-secondary-instance={isInitInstance ? true : false} style={isInitInstance ? {display: 'none'} : {}}>
                    <KoenigComposer
                        editorResource={this.editorResource}
                        cardConfig={cardConfig}
                        fileUploader={{useFileUpload, fileTypes}}
                        initialEditorState={this.args.lexical}
                        onError={this.onError}
                        darkMode={this.feature.nightShift}
                        isTKEnabled={true}
                    >
                        <KoenigEditor
                            editorResource={this.editorResource}
                            cursorDidExitAtTop={isInitInstance ? null : this.args.cursorDidExitAtTop}
                            placeholderText={isInitInstance ? null : this.args.placeholderText}
                            darkMode={isInitInstance ? null : this.feature.nightShift}
                            onChange={isInitInstance ? this.args.updateSecondaryInstanceModel : this.args.onChange}
                            registerAPI={isInitInstance ? this.args.registerSecondaryAPI : this.args.registerAPI}
                        />
                        <WordCountPlugin editorResource={this.editorResource} onChange={isInitInstance ? () => {} : this.args.updateWordCount} />
                        <TKCountPlugin editorResource={this.editorResource} onChange={isInitInstance ? () => {} : this.args.updatePostTkCount} />
                    </KoenigComposer>
                </div>
            );
        };

        return (
            <div className={['koenig-react-editor', 'koenig-lexical', this.args.className].filter(Boolean).join(' ')}>
                <ErrorHandler config={this.config}>
                    <Suspense fallback={<p className="koenig-react-editor-loading">Loading editor...</p>}>
                        <KGEditorComponent />
                        <KGEditorComponent isInitInstance={true} />
                    </Suspense>
                </ErrorHandler>
            </div>
        );
    };

    renderMemberLinks() {
        if (!this.membersUtils.paidMembersEnabled) {
            return [];
        }
        return [
            {
                label: 'Paid signup',
                value: '#/portal/signup'
            },
            {
                label: 'Upgrade or change plan',
                value: '#/portal/account/plans'
            }
        ];
    }

    renderDonationLink() {
        if (!this.settings.donationsEnabled) {
            return [];
        }
        return [{
            label: 'Tips and donations',
            value: '#/portal/support'
        }];
    }

    renderRecommendationLink() {
        if (!this.settings.recommendationsEnabled) {
            return [];
        }
        return [{
            label: 'Recommendations',
            value: '#/portal/recommendations'
        }];
    }

    getCachedDefaultLinks() {
        if (this.defaultLinks) {
            return this.defaultLinks;
        }

        return this.fetchDefaultLinks();
    }

    async fetchDefaultLinks() {
        const posts = await this.store.query('post', {
            filter: 'status:published',
            fields: 'id,url,title,visibility,published_at',
            order: 'published_at desc',
            limit: 5
        });

        const results = posts.toArray().map(post => ({
            groupName: 'Latest posts',
            id: post.id,
            title: post.title,
            url: post.url,
            visibility: post.visibility,
            publishedAt: post.publishedAtUTC.toISOString()
        }));

        results.forEach(item => decoratePostSearchResult(item, this.settings));

        this.defaultLinks = [{
            label: 'Latest posts',
            items: results
        }];

        return this.defaultLinks;
    }

    async performSearch(term) {
        let results = [];

        try {
            results = await this.search.searchTask.perform(term);
        } catch (error) {
            if (!didCancel(error)) {
                throw error;
            }
            return [];
        }

        const filteredResults = this.filterSearchResults(results);

        return filteredResults;
    }

    filterSearchResults(results) {
        const filteredResults = [];

        results.forEach((group) => {
            let items = group.options;

            if (group.groupName === 'Posts' || group.groupName === 'Pages') {
                items = items.filter(i => i.status === 'published');
            }

            if (group.groupName === 'Staff') {
                items = items.filter(i => !/\/404\//.test(i.url));
            }

            if (items.length === 0) {
                return;
            }

            if (group.groupName === 'Posts' || group.groupName === 'Pages') {
                items.forEach(item => decoratePostSearchResult(item, this.settings));
            }

            filteredResults.push({
                label: group.groupName,
                items
            });
        });

        return filteredResults;
    }

    createXhrWithProgress(file, updateProgress, progressTracker) {
        return function xhr() {
            const xhr = new window.XMLHttpRequest();

            xhr.upload.addEventListener('progress', (event) => {
                if (event.lengthComputable) {
                    progressTracker.current.set(file, (event.loaded / event.total) * 100);
                    updateProgress();
                }
            }, false);

            return xhr;
        };
    }

    extractUploadResponse(response, type) {
        let uploadResponse;
        try {
            uploadResponse = JSON.parse(response);
        } catch (error) {
            if (!(error instanceof SyntaxError)) {
                throw error;
            }
        }

        if (uploadResponse) {
            const resource = uploadResponse[fileTypes[type].resourceName];
            if (resource && Array.isArray(resource) && resource[0]) {
                return {
                    url: resource[0].url,
                    fileName: ''
                };
            }
        }

        return {
            url: undefined,
            fileName: ''
        };
    }

    processUploadError(error, file) {
        console.error(error); // eslint-disable-line

        let message = error.payload?.errors?.[0]?.message || '';
        let context = error.payload?.errors?.[0]?.context || '';

        if (!message) {
            message = error.message;
        }

        const errorResult = {
            message,
            context,
            fileName: file.name
        };

        throw errorResult;
    }
}

isPublic: computed('visibility', function () {
    return this.visibility === 'public';
}),

generateSession() {
    const sessionId = this.generateUuid();
    const pageCount = this.determineSessionPageCount();
    const firstContent = this.selectContent();
    let baseTimestamp = this.generateTimestamp(firstContent.published_at);
    const sessionContext = this.buildSessionContext();

    const events = [];
    for (let i = 0; i < pageCount; i++) {
        const content = i === 0 ? firstContent : this.selectContent();
        const timestamp = this.calculateSessionTimestamp(baseTimestamp, i);
        if (timestamp > new Date()) {
            break;
        }

        const event = this.buildSessionEvent(
            sessionId,
            content,
            timestamp,
            sessionContext,
            i === 0
        );
        events.push(event);
    }

    return events;
}

/**
 * Determine number of pages in session using weighted distribution
 */
determineSessionPageCount() {
    const r = Math.random();
    if (r < 0.4) {
        return 1;
    } else if (r < 0.7) {
        return 2 + Math.floor(Math.random() * 2);
    } else if (r < 0.9) {
        return 4 + Math.floor(Math.random() * 3);
    }
    return 7 + Math.floor(Math.random() * 4);
}

/**
 * Build consistent session attributes
 */
buildSessionContext() {
    const memberStatus = this.weightedChoice(this.memberStatusWeights);
    let memberUuid;
    if (memberStatus === 'undefined') {
        memberUuid = 'undefined';
    } else if (this.memberUuids.length > 0 && Math.random() < 0.7) {
        memberUuid = this.randomChoice(this.memberUuids);
    } else {
        memberUuid = this.generateUuid();
    }

    const referrer = this.weightedChoice(this.referrerWeights);
    const referrerSource = this.referrerSourceMap[referrer] || referrer;
    const utmParams = this.generateUtmParameters();
    const baseUrl = this.siteConfig.url || 'http://localhost:2368';

    return {
        memberUuid,
        memberStatus,
        userAgent: this.randomChoice(this.userAgents),
        locale: this.randomChoice(this.locales),
        location: this.weightedChoice(this.locationWeights),
        referrer,
        referrerSource,
        utmParams,
        baseUrl
    };
}

/**
 * Calculate timestamp for session page view
 */
calculateSessionTimestamp(baseTimestamp, index) {
    if (index === 0) {
        return baseTimestamp;
    }
    const offsetSeconds = 30 + Math.floor(Math.random() * 270);
    return new Date(baseTimestamp.getTime() + (index * offsetSeconds * 1000));
}

/**
 * Build analytics event for session page view
 */
buildSessionEvent(sessionId, content, timestamp, context, isFirstPage) {
    const href = this.buildHref(content.pathname, context.utmParams, isFirstPage, context.baseUrl);
    const payload = {
        site_uuid: this.siteUuid,
        member_uuid: context.memberUuid,
        member_status: context.memberStatus,
        post_uuid: content.post_uuid,
        post_type: content.post_type,
        'user-agent': context.userAgent,
        locale: context.locale,
        location: context.location,
        referrer: isFirstPage ? context.referrer : '',
        pathname: content.pathname,
        href: href,
        meta: {
            referrerSource: isFirstPage ? context.referrerSource : ''
        }
    };

    if (isFirstPage && context.utmParams) {
        Object.assign(payload, context.utmParams);
    }

    return {
        timestamp: this.formatTimestamp(timestamp),
        session_id: sessionId,
        action: 'page_hit',
        version: '1',
        payload: payload
    };
}

/**
 * Build href with optional UTM parameters
 */
buildHref(pathname, utmParams, includeUtm, baseUrl) {
    let href = `${baseUrl}${pathname}`;
    if (includeUtm && utmParams) {
        const utmQueryString = Object.entries(utmParams)
            .filter(([, value]) => value !== undefined)
            .map(([key, value]) => `${key}=${encodeURIComponent(value)}`)
            .join('&');
        if (utmQueryString) {
            href = `${href}?${utmQueryString}`;
        }
    }
    return href;
}

