        bannerImageUrl
    }: {
        name: string;
        username: string;
        bio: string;
        avatarUrl: string;
        bannerImageUrl: string;
    }) {
        const url = new URL(`.ghost/activitypub/v1/account`, this.apiUrl);

        await this.fetchJSON(url, 'PUT', {
            name,
            username,
            bio,
            avatarUrl,
            bannerImageUrl
        });
    }

    async upload(file: File): Promise<string> {
        const url = new URL('.ghost/activitypub/v1/upload/image', this.apiUrl);
        const formData = new FormData();
        formData.append('file', file);

        const token = await this.getToken();
        const response = await this.fetch(url, {
            method: 'POST',
            headers: {
                Authorization: `Bearer ${token}`
            },
            body: formData
        });

        if (!response.ok) {
            throw {
                message: 'Upload failed',
                statusCode: response.status
            };
        }

        const json = await response.json();
        return json.fileUrl;
    }

    async enableBluesky() {
        const url = new URL('.ghost/activitypub/v2/actions/bluesky/enable', this.apiUrl);

        await this.fetchJSON(url, 'POST');
    }

    async disableBluesky() {
        const url = new URL('.ghost/activitypub/v2/actions/bluesky/disable', this.apiUrl);

        await this.fetchJSON(url, 'POST');
    }

    async confirmBlueskyHandle(): Promise<string> {
        const url = new URL('.ghost/activitypub/v2/actions/bluesky/confirm-handle', this.apiUrl);

        const json = await this.fetchJSON(url, 'POST');

        if (json === null || !('handle' in json) || typeof json.handle !== 'string') {
            return '';
        }

        return String(json.handle);
    }

    private extractArray<T>(json: unknown, key: string): T[] {
        if (!json || typeof json !== 'object') {
            return [];
        }

        const value = (json as Record<string, unknown>)[key];
        return Array.isArray(value) ? value as T[] : [];
    }

    private extractNext(json: unknown): string | null {
        if (!json || typeof json !== 'object') {
            return null;
        }

        const next = (json as Record<string, unknown>).next;
        return typeof next === 'string' ? next : null;
    }

    private parsePaginatedResponse<T>(json: unknown, key: string): {accounts: T[], next: string | null} {
        const accounts = this.extractArray<T>(json, key);
        const next = this.extractNext(json);

        return {
            accounts,
            next
        };
    }
}

