                    >
                        {this.text}
                    </p>
                    {this.renderLoginMessage(brandColor, doAction)}
                </div>
            </section>
        );
    }
}

class PaidMembersOnlyMessage extends NotificationMessage {
    constructor() {
        super({
            text: t('This site only accepts paid members.'),
