     * @param {string|null} imageValue - new image value
     * @returns {Promise<void>|undefined}
     */
    _handleImageUpdate(imageAttr, imageValue) {
        this.set('post.' + imageAttr, imageValue);

        if (this.get('post.isNew')) {
            return;
