    edit(data, unfilteredOptions) {
        const options = this.filterOptions(unfilteredOptions, 'edit');
        if (!Array.isArray(data)) {
            data = [data];
        }

        return Promise.all(data.map(item => this._editSingleSetting(item, options)));
