    _collectMissingDefaults(usedKeys) {
        const defaults = getDefaultSettings();
        const settingsToInsert = [];

        _.each(defaults, (defaultSetting, defaultSettingKey) => {
            if (usedKeys.indexOf(defaultSettingKey) === -1) {
