const getDeviceLabel = (device: string): string => {
    if (device === 'mobile-ios') {
        return 'iOS';
    }
    if (device === 'mobile-android') {
        return 'Android';
    }
    if (device === 'desktop') {
        return 'Desktop';
    }
    if (device === 'bot') {
        return 'Bot';
    }
    if (device === 'unknown') {
        return 'Unknown';
    }
    return device;
};

