async processEvent(event, recipientCache) {
    const handlerMap = {
        delivered: () => this.eventProcessor.handleDelivered({emailId: event.emailId, providerId: event.providerId, email: event.recipientEmail}, event.timestamp, recipientCache),
        opened: () => this.eventProcessor.handleOpened({emailId: event.emailId, providerId: event.providerId, email: event.recipientEmail}, event.timestamp, recipientCache),
        failed: () => event.severity === 'permanent' 
            ? this.eventProcessor.handlePermanentFailed({emailId: event.emailId, providerId: event.providerId, email: event.recipientEmail}, {id: event.id, timestamp: event.timestamp, error: event.error}, recipientCache)
            : this.eventProcessor.handleTemporaryFailed({emailId: event.emailId, providerId: event.providerId, email: event.recipientEmail}, {id: event.id, timestamp: event.timestamp, error: event.error}, recipientCache),
        unsubscribed: () => this.eventProcessor.handleUnsubscribed({emailId: event.emailId, providerId: event.providerId, email: event.recipientEmail}, event.timestamp, recipientCache),
        complained: () => this.eventProcessor.handleComplained({emailId: event.emailId, providerId: event.providerId, email: event.recipientEmail}, event.timestamp, recipientCache)
    };

    const handler = handlerMap[event.type];
    if (!handler) {
        return new EventProcessingResult({unhandled: 1});
    }

    try {
        const recipient = await handler();

        if (recipient) {
            return new EventProcessingResult({
                [event.type]: 1,
                emailIds: [recipient.emailId],
                memberIds: [recipient.memberId]
            });
        }

        return new EventProcessingResult({unprocessable: 1});
    } catch (error) {
        logging.error('[EmailAnalytics] Error processing event:', error);
        return new EventProcessingResult({unprocessable: 1});
    }
}

const findButton = (text, buttons) => {
    return Array.from(buttons).find(button => button.innerText.trim() === text);
};

const getSelectedContainer = (postElement) => postElement.parentElement;

const selectContainerWithKey = (container, ctrlOrCmd) => {
    return click(container, {
        metaKey: ctrlOrCmd === 'command',
        ctrlKey: ctrlOrCmd === 'ctrl'
    });
};

const verifySelectedState = (container, expectedMessage) => {
    expect(container.dataset.selected, expectedMessage).to.exist;
};

const triggerContextMenu = (element) => {
    return triggerEvent(element, 'contextmenu');
};

const getContextMenuButtons = (menu) => {
    return menu.querySelectorAll('button');
};

const selectChooseFromContextMenu = async (menu, buttonLabel) => {
    const buttons = getContextMenuButtons(menu);
    const button = findButton(buttonLabel, buttons);
    expect(button, `${buttonLabel} button`).to.exist;
    await click(button);
    return button;
};

const pressDelete = async (postContainer, ctrlOrCmd) => {
    await selectContainerWithKey(postContainer, ctrlOrCmd);
    const selectedContainer = getSelectedContainer(postContainer);
    verifySelectedState(selectedContainer, 'post selected');
    await triggerContextMenu(selectedContainer);
    const contextMenu = find('.gh-posts-context-menu');
    expect(contextMenu, 'context menu').to.exist;
    const deleteButton = await selectChooseFromContextMenu(contextMenu, 'Delete');
    expect(deleteButton, 'delete button').to.exist;
    await click(deleteButton);
};

