                paddingClasses: 'p-10',
                headerClasses: '-inset-x-10 -top-10'
            };
        case 'full':
            return {
                modalClasses: 'h-full',
                backdropClasses: 'p-4 md:p-[3vmin]',
                paddingClasses: 'p-10',
                headerClasses: '-inset-x-10'
            };
        case 'bleed':
            return {
