            .model('User')
            .where(query)
            .fetch(Object.assign({columns: ['id']}, _.pick(options, 'transacting')));

        const userId = user ? user.id : ownerUser.id;
        const userExists = authorsToSet.find(a => a && a.id === userId.id);

        if (!userExists) {
            authorsToSet[index] = {id: userId};
