                    });
            }

            function isChangingAuthors() {
                if (!unsafeAttrs?.authors) {
                    return false;
                }

                if (!unsafeAttrs.authors.length) {
                    return true;
                }

                const existingPrimaryAuthor = postModel?.related('authors')?.models?.[0];
                return unsafeAttrs.authors[0].id !== existingPrimaryAuthor?.id;
            }

            function isOwner() {
                if (!unsafeAttrs?.authors?.length) {
                    return false;
                }
                return unsafeAttrs.authors[0].id === context.user;
            }

            function isPrimaryAuthor() {
                return context.user === postModel?.related('authors')?.models?.[0]?.id;
            }

            function isCoAuthor() {
                return postModel?.related('authors')?.models
                    ?.map(author => author.id)
                    ?.includes(context.user) || false;
            }

            return getPostModel(postModelOrId).then(postModel => {
                if (isContributor && isEdit) {
                    hasUserPermission = !isChangingAuthors() && isCoAuthor();
                } else if (isContributor && isAdd) {
                    hasUserPermission = isOwner();
                } else if (isContributor && isDestroy) {
                    hasUserPermission = isPrimaryAuthor();
                } else if (isAuthor && isEdit) {
                    hasUserPermission = isCoAuthor() && !isChangingAuthors();
                } else if (isAuthor && isAdd) {
                    hasUserPermission = isOwner();
                } else if (postModel) {
                    hasUserPermission = hasUserPermission || isPrimaryAuthor();
                }

                if (hasUserPermission && hasApiKeyPermission) {
                    return Post.permissible.call(
                        this,
                        postModelOrId,
                        action,
                        context,
                        unsafeAttrs,
                        loadedPermissions,
                        hasUserPermission,
                        hasApiKeyPermission
                    ).then(({excludedAttrs}) => {
                        if (isContributor || isAuthor) {
                            return {excludedAttrs: ['authors'].concat(excludedAttrs)};
                        }
                        return {excludedAttrs};
                    });
                }

                return Promise.reject(new errors.NoPermissionError({
                    message: tpl(messages.notEnoughPermission)
                }));
            });
        }
    });

    return Model;
};

const mapped = posts.data.map((post) => {
    let email = post.related('email');

    // Weird bookshelf thing fix
    if (!email.id) {
        email = null;
    }

    let published = true;
    if (post.get('status') === 'draft' || post.get('status') === 'scheduled') {
        email = null;
        published = false;
    }

    const feedbackEnabled = email?.get('feedback_enabled') && hasNewslettersWithFeedback;
    const showEmailClickAnalytics = trackClicks && email?.get('track_clicks');

    const feedbackMoreLikeThis = feedbackEnabled ? post.get('count__positive_feedback') ?? 0 : null;
    const feedbackLessLikeThis = feedbackEnabled ? post.get('count__negative_feedback') ?? 0 : null;

    const opens = trackOpens ? email?.get('opened_count') ?? null : null;
    const clicks = showEmailClickAnalytics ? post.get('count__clicks') ?? 0 : null;
    const signups = membersTrackSources && published ? post.get('count__signups') ?? 0 : null;
    const paidConversions = membersTrackSources && paidMembersEnabled && published ? post.get('count__paid_conversions') ?? 0 : null;

    return {
        id: post.get('id'),
        title: post.get('title'),
        url: this.#getPostUrl(post),
        author: post.related('authors').map(author => author.get('name')).join(', '),
