                  loader: require.resolve('file-loader'),
                  options: { name: 'static/media/[name].[hash].[ext]' },
                },
              ],
              issuer: { and: [/\.(ts|tsx|js|jsx|md|mdx)$/] },
            },
            {
              test: /\.(js|mjs|jsx|ts|tsx)$/,
              include: paths.appSrc,
              loader: require.resolve('babel-loader'),
              options: buildBabelLoaderOptions(isEnvDevelopment, isEnvProduction, shouldUseReactRefresh, hasJsxRuntime),
            },
            {
              test: /\.(js|mjs)$/,
              exclude: /@babel(?:\/|\\{1,2})runtime/,
              loader: require.resolve('babel-loader'),
              options: buildExternalBabelLoaderOptions(isEnvDevelopment, isEnvProduction, shouldUseSourceMap),
            },
            {
              test: cssRegex,
              exclude: cssModuleRegex,
              use: buildStyleLoaders(
                {
                  importLoaders: 1,
                  sourceMap: isEnvProduction ? shouldUseSourceMap : isEnvDevelopment,
                  modules: { mode: 'icss' },
                },
                null,
                isEnvDevelopment,
                isEnvProduction,
                shouldUseSourceMap
              ),
              sideEffects: true,
            },
            {
              test: cssModuleRegex,
              use: buildStyleLoaders(
                {
                  importLoaders: 1,
                  sourceMap: isEnvProduction ? shouldUseSourceMap : isEnvDevelopment,
                  modules: {
                    mode: 'local',
                    getLocalIdent: getCSSModuleLocalIdent,
                  },
                },
                null,
                isEnvDevelopment,
                isEnvProduction,
                shouldUseSourceMap
              ),
            },
            {
              test: sassRegex,
              exclude: sassModuleRegex,
              use: buildStyleLoaders(
                {
                  importLoaders: 3,
                  sourceMap: isEnvProduction ? shouldUseSourceMap : isEnvDevelopment,
                  modules: { mode: 'icss' },
                },
                'sass-loader',
                isEnvDevelopment,
                isEnvProduction,
                shouldUseSourceMap
              ),
              sideEffects: true,
            },
            {
              test: sassModuleRegex,
              use: buildStyleLoaders(
                {
                  importLoaders: 3,
                  sourceMap: isEnvProduction ? shouldUseSourceMap : isEnvDevelopment,
                  modules: {
                    mode: 'local',
                    getLocalIdent: getCSSModuleLocalIdent,
                  },
                },
                'sass-loader',
                isEnvDevelopment,
                isEnvProduction,
                shouldUseSourceMap
              ),
            },
            {
              exclude: [/^$/, /\.(js|mjs|jsx|ts|tsx)$/, /\.html$/, /\.json$/],
              type: 'asset/resource',
            },
          ],
        },
      ].filter(Boolean),
    },
    plugins: [
      buildHtmlPluginConfig(isEnvProduction),
      isEnvProduction && shouldInlineRuntimeChunk && new InlineChunkHtmlPlugin(HtmlWebpackPlugin, [/runtime-.+[.]js/]),
      new InterpolateHtmlPlugin(HtmlWebpackPlugin, env.raw),
      new ModuleNotFoundPlugin(paths.appPath),
      new webpack.DefinePlugin(env.stringified),
      isEnvDevelopment && shouldUseReactRefresh && new ReactRefreshWebpackPlugin({ overlay: false }),
      isEnvDevelopment && new CaseSensitivePathsPlugin(),
      isEnvProduction && buildMiniCssExtractPluginConfig(),
      buildWebpackManifestPluginConfig(),
      new webpack.IgnorePlugin({ resourceRegExp: /^\.\/locale$/, contextRegExp: /moment$/ }),
      isEnvProduction && fs.existsSync(swSrc) && buildWorkboxPluginConfig(),
      useTypeScript && buildForkTsCheckerPluginConfig(isEnvDevelopment, useTypeScript),
      !disableESLintPlugin && buildESLintPluginConfig(isEnvDevelopment, emitErrorsAsWarnings, hasJsxRuntime),
    ].filter(Boolean),
    performance: false,
  };
};

function isReactInstalled(appPackage) {
  const dependencies = appPackage.dependencies || {};

  return (
    typeof dependencies.react !== 'undefined' &&
    typeof dependencies['react-dom'] !== 'undefined'
  );
}

function getTemplatePackageToMerge(templatePackageToReplace, templatePackageBlacklist, templatePackage) {
  return ['dependencies', 'scripts'];
}

function filterTemplatePackageKeys(templatePackage, templatePackageBlacklist, templatePackageToMerge) {
  return Object.keys(templatePackage).filter(key => {
    return (
      !templatePackageBlacklist.includes(key) &&
      !templatePackageToMerge.includes(key)
    );
  });
}

function updatePackageJsonWithTemplate(
  appPackage,
  templatePackage,
  templatePackageToMerge,
  templatePackageToReplace
) {
  appPackage.dependencies = appPackage.dependencies || {};
  appPackage.scripts = Object.assign(
    {
      start: 'react-scripts start',
      build: 'react-scripts build',
      test: 'react-scripts test',
      eject: 'react-scripts eject',
    },
    templatePackage.scripts || {}
  );

  templatePackageToReplace.forEach(key => {
    appPackage[key] = templatePackage[key];
  });

  fs.writeFileSync(
    path.join(appPath, 'package.json'),
    JSON.stringify(appPackage, null, 2) + os.EOL
  );
}

function updatePackageJsonScriptsForYarn(appPackage, useYarn) {
  if (useYarn) {
    appPackage.scripts = Object.entries(appPackage.scripts).reduce(
      (acc, [key, value]) => ({
        ...acc,
        [key]: value.replace(/(npm run |npm )/, 'yarn '),
      }),
      {}
    );
  }
}

function updateReadmeForYarn(appPath, useYarn) {
  if (useYarn) {
    try {
      const readme = fs.readFileSync(path.join(appPath, 'README.md'), 'utf8');
      fs.writeFileSync(
        path.join(appPath, 'README.md'),
        readme.replace(/(npm run |npm )/g, 'yarn '),
        'utf8'
      );
    } catch (err) {
      // Silencing the error
    }
  }
}

function handleGitignore(appPath) {
  const gitignoreExists = fs.existsSync(path.join(appPath, '.gitignore'));
  if (gitignoreExists) {
    const data = fs.readFileSync(path.join(appPath, 'gitignore'));
    fs.appendFileSync(path.join(appPath, '.gitignore'), data);
    fs.unlinkSync(path.join(appPath, 'gitignore'));
  } else {
    fs.moveSync(
      path.join(appPath, 'gitignore'),
      path.join(appPath, '.gitignore'),
      []
    );
  }
}

function installDependencies(appPath, appPackage, templatePackage, useYarn, command, verbose) {
  let args;

  if (useYarn) {
    args = ['add'];
  } else {
    args = [
      'install',
      '--no-audit',
      '--save',
      verbose && '--verbose',
    ].filter(e => e);
  }

  const dependenciesToInstall = Object.entries({
    ...templatePackage.dependencies,
    ...templatePackage.devDependencies,
  });
  if (dependenciesToInstall.length) {
    args = args.concat(
      dependenciesToInstall.map(([dependency, version]) => {
        return `${dependency}@${version}`;
      })
    );
  }

  if (!isReactInstalled(appPackage)) {
    args = args.concat(['react', 'react-dom']);
  }

  if ((!isReactInstalled(appPackage) || templateName) && args.length > 1) {
    console.log();
    console.log(`Installing template dependencies using ${command}...`);

    const proc = spawn.sync(command, args, { stdio: 'inherit' });
    if (proc.status !== 0) {
      console.error(`\`${command} ${args.join(' ')}\` failed`);
      return false;
    }
  }

  if (args.find(arg => arg.includes('typescript'))) {
    console.log();
    verifyTypeScriptSetup();
  }

  return true;
}

