}

function isReactInstalled(appPackage) {
  const deps = appPackage.dependencies || {};
  return typeof deps.react !== 'undefined' && typeof deps['react-dom'] !== 'undefined';
}

module.exports = initProject;

module.exports = function (
  appPath,
  appName,
  verbose,
  originalDirectory,
  templateName
) {
  const appPackage = require(path.join(appPath, 'package.json'));
  const useYarn = fs.existsSync(path.join(appPath, 'yarn.lock'));

  if (!templateName) {
    handleMissingTemplate();
    return;
  }

  const templatePath = path.dirname(
    require.resolve(`${templateName}/package.json`, { paths: [appPath] })
  );
  const templateJsonPath = path.join(templatePath, 'template.json');

  let templateJson = {};
  if (fs.existsSync(templateJsonPath)) {
    templateJson = require(templateJsonPath);
  }

  const templatePackage = templateJson.package || {};
  validateTemplateStructure(templateJson);
  const shouldInstallReact = !isReactInstalled(appPackage);

  prepareAppPackage(appPackage, templatePackage, useYarn, templateJson);
  updateReadmeIfPresent(appPath, useYarn);
  handleGitignore(appPath);
  copyTemplateFiles(appPath, templatePath);

  const initializedGit = initializeGitRepo();
  const dependenciesToInstall = buildDependenciesList(
    appPackage,
    templatePackage,
    shouldInstallReact
  );

  if (dependenciesToInstall.length > 0) {
    installDependencies(appPath, useYarn, dependenciesToInstall);
  }

  if (dependenciesToInstall.includes('typescript')) {
    verifyTypeScriptSetup();
  }

  removeTemplatePackage(appPath, useYarn, templateName);

  if (initializedGit) {
    tryGitCommit(appPath);
  }

  showSuccessMessage(
    appPath,
    appName,
    originalDirectory,
    useYarn,
    readmeExists
  );
};

function handleMissingTemplate() {
  console.log('');
  console.error(
    `A template was not provided. This is likely because you're using an outdated version of ${chalk.cyan(
      'create-react-app'
    )}.`
  );
  console.error(
    `Please note that global installs of ${chalk.cyan(
      'create-react-app'
    )} are no longer supported.`
  );
  console.error(
    `You can fix this by running ${chalk.cyan(
      'npm uninstall -g create-react-app'
    )} or ${chalk.cyan(
      'yarn global remove create-react-app'
    )} before using ${chalk.cyan('create-react-app')} again.`
  );
}

function validateTemplateStructure(templateJson) {
  if (templateJson.dependencies || templateJson.scripts) {
    console.log();
    console.log(
      chalk.red(
        'Root-level `dependencies` and `scripts` keys in `template.json` were deprecated for Create React App 5.\n' +
          'This template needs to be updated to use the new `package` key.'
      )
    );
    console.log('For more information, visit https://cra.link/templates');
  }
}

function prepareAppPackage(appPackage, templatePackage, useYarn, templateJson) {
  setupScripts(appPackage, templatePackage, useYarn);
  setupESLintConfig(appPackage);
  setupBrowserslist(appPackage);
  mergeTemplatePackageKeys(appPackage, templatePackage);
  writePackageJson(appPackage);
}

function setupScripts(appPackage, templatePackage, useYarn) {
  const defaultScripts = {
    start: 'react-scripts start',
    build: 'react-scripts build',
    test: 'react-scripts test',
    eject: 'react-scripts eject',
  };

  const templateScripts = templatePackage.scripts || {};
  appPackage.scripts = Object.assign(defaultScripts, templateScripts);

  if (useYarn) {
    appPackage.scripts = Object.entries(appPackage.scripts).reduce(
      (acc, [key, value]) => ({
        ...acc,
        [key]: value.replace(/(npm run |npm )/, 'yarn '),
      }),
      {}
    );
  }
}

function setupESLintConfig(appPackage) {
  appPackage.eslintConfig = {
    extends: 'react-app',
  };
}

function setupBrowserslist(appPackage) {
  appPackage.browserslist = defaultBrowsers;
}

function mergeTemplatePackageKeys(appPackage, templatePackage) {
  const blacklist = [
    'name',
    'version',
    'description',
    'keywords',
    'bugs',
    'license',
    'author',
    'contributors',
    'files',
    'browser',
    'bin',
    'man',
    'directories',
    'repository',
    'peerDependencies',
    'bundledDependencies',
    'optionalDependencies',
    'engineStrict',
    'os',
    'cpu',
    'preferGlobal',
    'private',
    'publishConfig',
  ];

  const mergeKeys = ['dependencies', 'scripts'];
  const replaceKeys = Object.keys(templatePackage).filter(
    key => !blacklist.includes(key) && !mergeKeys.includes(key)
  );

  replaceKeys.forEach(key => {
    appPackage[key] = templatePackage[key];
  });
}

function writePackageJson(appPackage) {
  fs.writeFileSync(
    path.join(appPath, 'package.json'),
    JSON.stringify(appPackage, null, 2) + os.EOL
  );
}

function updateReadmeIfPresent(appPath, useYarn) {
  const readmePath = path.join(appPath, 'README.md');
  if (!fs.existsSync(readmePath)) return;

  fs.renameSync(readmePath, path.join(appPath, 'README.old.md'));
}

function handleGitignore(appPath) {
  const gitignorePath = path.join(appPath, '.gitignore');
  const gitignoreContentPath = path.join(appPath, 'gitignore');

  if (fs.existsSync(gitignorePath)) {
    const data = fs.readFileSync(gitignoreContentPath);
    fs.appendFileSync(gitignorePath, data);
    fs.unlinkSync(gitignoreContentPath);
  } else if (fs.existsSync(gitignoreContentPath)) {
    fs.moveSync(gitignoreContentPath, gitignorePath, []);
  }
}

function copyTemplateFiles(appPath, templatePath) {
  const templateDir = path.join(templatePath, 'template');
  if (!fs.existsSync(templateDir)) {
    console.error(
      `Could not locate supplied template: ${chalk.green(templateDir)}`
    );
    return;
  }
  fs.copySync(templateDir, appPath);

  if (useYarn) {
    try {
      const readme = fs.readFileSync(path.join(appPath, 'README.md'), 'utf8');
      fs.writeFileSync(
        path.join(appPath, 'README.md'),
        readme.replace(/(npm run |npm )/g, 'yarn '),
        'utf8'
      );
    } catch (err) {
      // Silencing the error as it falls back to using default npm commands.
    }
  }
}

function initializeGitRepo() {
  if (tryGitInit()) {
    console.log();
    console.log('Initialized a git repository.');
    return true;
  }
  return false;
}

function buildDependenciesList(appPackage, templatePackage, shouldInstallReact) {
  const dependenciesToInstall = [];

  const mergedDeps = {
    ...templatePackage.dependencies,
    ...templatePackage.devDependencies,
  };

  Object.entries(mergedDeps).forEach(([dependency, version]) => {
    dependenciesToInstall.push(`${dependency}@${version}`);
  });

  if (shouldInstallReact) {
    dependenciesToInstall.push('react', 'react-dom');
  }

  return dependenciesToInstall;
}

function installDependencies(appPath, useYarn, dependenciesToInstall) {
  const command = useYarn ? 'yarnpkg' : 'npm';
  const argsBase = useYarn ? ['add'] : ['install', '--no-audit', '--save'];

  if (verbose) {
    argsBase.push('--verbose');
  }

  const args = argsBase.concat(dependenciesToInstall);

  console.log();
  console.log(`Installing template dependencies using ${command}...`);
  const proc = spawn.sync(command, args, { stdio: 'inherit' });

  if (proc.status !== 0) {
    console.error(`\`${command} ${args.join(' ')}\` failed`);
  }
}

function removeTemplatePackage(appPath, useYarn, templateName) {
  const removeCmd = useYarn ? 'remove' : 'uninstall';
  const command = useYarn ? 'yarnpkg' : 'npm';

  console.log(`Removing template package using ${command}...`);
  console.log();
  const proc = spawn.sync(command, [removeCmd, templateName], {
    stdio: 'inherit',
  });

  if (proc.status !== 0) {
    console.error(`\`${command} ${removeCmd} ${templateName}\` failed`);
  }
}

function showSuccessMessage(
  appPath,
  appName,
  originalDirectory,
  useYarn,
  readmeExists
) {
  let cdpath;
  if (
    originalDirectory &&
    path.join(originalDirectory, appName) === appPath
  ) {
    cdpath = appName;
  } else {
    cdpath = appPath;
  }

  const displayedCommand = useYarn ? 'yarn' : 'npm';

  console.log();
  console.log(`Success! Created ${appName} at ${appPath}`);
  console.log('Inside that directory, you can run several commands:');
  console.log();
  console.log(chalk.cyan(`  ${displayedCommand} start`));
  console.log('    Starts the development server.');
  console.log();
  console.log(
    chalk.cyan(`  ${displayedCommand} ${useYarn ? '' : 'run '}build`)
  );
  console.log('    Bundles the app into static files for production.');
  console.log();
  console.log(chalk.cyan(`  ${displayedCommand} test`));
  console.log('    Starts the test runner.');
  console.log();
  console.log(
    chalk.cyan(`  ${displayedCommand} ${useYarn ? '' : 'run '}eject`)
  );
  console.log(
    '    Removes this tool and copies build dependencies, configuration files'
  );
  console.log(
    '    and scripts into the app directory. If you do this, you can’t go back!'
  );
  console.log();
  console.log('We suggest that you begin by typing:');
  console.log();
  console.log(chalk.cyan('  cd'), cdpath);
  console.log(`  ${chalk.cyan(`${displayedCommand} start`)}`);

  if (readmeExists) {
    console.log();
    console.log(
      chalk.yellow(
        'You had a `README.md` file, we renamed it to `README.old.md`'
      )
    );
  }
  console.log();
  console.log('Happy hacking!');
}

'use strict';

const fs = require('fs');
const path = require('path');
const webpack = require('webpack');
const resolve = require('resolve');
const HtmlWebpackPlugin = require('html-webpack-plugin');
const CaseSensitivePathsPlugin = require('case-sensitive-paths-webpack-plugin');
const InlineChunkHtmlPlugin = require('react-dev-utils/InlineChunkHtmlPlugin');
const TerserPlugin = require('terser-webpack-plugin');
const MiniCssExtractPlugin = require('mini-css-extract-plugin');
const CssMinimizerPlugin = require('css-minimizer-webpack-plugin');
const { WebpackManifestPlugin } = require('webpack-manifest-plugin');
const InterpolateHtmlPlugin = require('react-dev-utils/InterpolateHtmlPlugin');
const WorkboxWebpackPlugin = require('workbox-webpack-plugin');
const ModuleScopePlugin = require('react-dev-utils/ModuleScopePlugin');
const getCSSModuleLocalIdent = require('react-dev-utils/getCSSModuleLocalIdent');
const ESLintPlugin = require('eslint-webpack-plugin');
const paths = require('./paths');
const modules = require('./modules');
const getClientEnvironment = require('./env');
const ModuleNotFoundPlugin = require('react-dev-utils/ModuleNotFoundPlugin');
const ForkTsCheckerWebpackPlugin =
  process.env.TSC_COMPILE_ON_ERROR === 'true'
    ? require('react-dev-utils/ForkTsCheckerWarningWebpackPlugin')
    : require('react-dev-utils/ForkTsCheckerWebpackPlugin');
const ReactRefreshWebpackPlugin = require('@pmmmwh/react-refresh-webpack-plugin');
const getCacheIdentifier = require('react-dev-utils/getCacheIdentifier');
const createEnvironmentHash = require('./webpack/persistentCache/createEnvironmentHash');

const shouldUseSourceMap = process.env.GENERATE_SOURCEMAP !== 'false';

const reactRefreshRuntimeEntry = require.resolve('react-refresh/runtime');
const reactRefreshWebpackPluginRuntimeEntry = require.resolve(
  '@pmmmwh/react-refresh-webpack-plugin'
);
const babelRuntimeEntry = require.resolve('babel-preset-react-app');
const babelRuntimeEntryHelpers = require.resolve(
  '@babel/runtime/helpers/esm/assertThisInitialized',
  { paths: [babelRuntimeEntry] }
);
const babelRuntimeRegenerator = require.resolve('@babel/runtime/regenerator', {
  paths: [babelRuntimeEntry],
});

const shouldInlineRuntimeChunk = process.env.INLINE_RUNTIME_CHUNK !== 'false';

const emitErrorsAsWarnings = process.env.ESLINT_NO_DEV_ERRORS === 'true';
const disableESLintPlugin = process.env.DISABLE_ESLINT_PLUGIN === 'true';

const imageInlineSizeLimit = parseInt(
  process.env.IMAGE_INLINE_SIZE_LIMIT || '10000'
);

const useTypeScript = fs.existsSync(paths.appTsConfig);
const useTailwind = fs.existsSync(path.join(paths.appPath, 'tailwind.config.js'));
const swSrc = paths.swSrc;

const cssRegex = /\.css$/;
const cssModuleRegex = /\.module\.css$/;
const sassRegex = /\.(scss|sass)$/;
const sassModuleRegex = /\.module\.(scss|sass)$/;

const hasJsxRuntime = (() => {
  if (process.env.DISABLE_NEW_JSX_TRANSFORM === 'true') return false;
  try {
    require.resolve('react/jsx-runtime');
    return true;
  } catch (e) {
    return false;
  }
})();

const isEnvDevelopment = webpackEnv => webpackEnv === 'development';
const isEnvProduction = webpackEnv => webpackEnv === 'production';
const isEnvProductionProfile = (webpackEnv, argv) =>
  isEnvProduction(webpackEnv) && argv.includes('--profile');

/**
 * @param {string[]} excludedPatterns
 * @return {string[]}
 */
const filterBooleanLoaders = excludedPatterns => loaders =>
  loaders.filter(loader => !excludedPatterns.includes(loader));

/**
 * @param {string} envStage
 * @param {string[]} dependencies
 * @return {string}
 */
const getCacheIdForBabel = (envStage, dependencies) =>
  getCacheIdentifier(
    envStage,
    dependencies
  );

/**
 * @param {Record<string, any>} cssOptions
 * @param {string|undefined} preProcessor
 * @return {any[]}
 */
const getStyleLoaders = (cssOptions, preProcessor) => {
  const isDev = false; // Will be patched at usage
  const loaders = [
    isDev && require.resolve('style-loader'),
    {
      loader: MiniCssExtractPlugin.loader,
      options: paths.publicUrlOrPath.startsWith('.')
        ? { publicPath: '../../' }
        : {},
    },
    {
      loader: require.resolve('css-loader'),
      options: cssOptions,
    },
    {
      loader: require.resolve('postcss-loader'),
      options: {
        postcssOptions: {
          ident: 'postcss',
          config: false,
          plugins: !useTailwind
            ? [
                'postcss-flexbugs-fixes',
                [
                  'postcss-preset-env',
                  {
                    autoprefixer: { flexbox: 'no-2009' },
                    stage: 3,
                  },
                ],
                'postcss-normalize',
              ]
            : [
                'tailwindcss',
                'postcss-flexbugs-fixes',
                [
                  'postcss-preset-env',
                  {
                    autoprefixer: { flexbox: 'no-2009' },
                    stage: 3,
                  },
                ],
              ],
        },
        sourceMap: shouldUseSourceMap && !isDev,
      },
    },
  ].filter(Boolean);

  if (preProcessor) {
    loaders.push(
      {
        loader: require.resolve('resolve-url-loader'),
        options: {
          sourceMap: shouldUseSourceMap,
          root: paths.appSrc,
        },
      },
      {
        loader: require.resolve(preProcessor),
        options: { sourceMap: true },
      }
    );
  }

  return loaders;
};

const getOptimizationMinimizer = (isProd, isProfile) => {
  const isProdEnv = isEnvProduction('production');
  return [
    new TerserPlugin({
      terserOptions: {
        parse: { ecma: 8 },
        compress: {
          ecma: 5,
          warnings: false,
          comparisons: false,
          inline: 2,
        },
        mangle: { safari10: true },
        keep_classnames: isProfile,
        keep_fnames: isProfile,
        output: { ecma: 5, comments: false, ascii_only: true },
      },
    }),
    new CssMinimizerPlugin(),
  ];
};

const getBabelPresets = hasJsxRuntime => [
  [
    require.resolve('babel-preset-react-app'),
    {
      runtime: hasJsxRuntime ? 'automatic' : 'classic',
    },
  ],
];

const getBabelOptions = (cacheIdentifier, plugins, isProd) => ({
  customize: require.resolve('babel-preset-react-app/webpack-overrides'),
  presets: getBabelPresets(isProd),
  babelrc: false,
  configFile: false,
  cacheIdentifier,
  plugins,
  cacheDirectory: true,
  cacheCompression: false,
  compact: isProd,
});

const get AliasConfig = (isProfile, isProd) => ({
  'react-native': 'react-native-web',
  ...(isProfile && {
    'react-dom$': 'react-dom/profiling',
    'scheduler/tracing': 'scheduler/tracing-profiling',
  }),
  ...(modules.webpackAliases || {}),
});

const getResolvePlugins = () => [
  new ModuleScopePlugin(paths.appSrc, [
    reactRefreshRuntimeEntry,
    reactRefreshWebpackPluginRuntimeEntry,
    babelRuntimeEntry,
    babelRuntimeEntryHelpers,
    babelRuntimeRegenerator,
  ]),
];

const getRuleForAvif = () => ({
  test: [/\.avif$/],
  type: 'asset',
  mimetype: 'image/avif',
  parser: { dataUrlCondition: { maxSize: imageInlineSizeLimit } },
});

const getRuleForImages = () => ({
  test: [/\.bmp$/, /\.gif$/, /\.jpe?g$/, /\.png$/],
  type: 'asset',
  parser: { dataUrlCondition: { maxSize: imageInlineSizeLimit } },
});

const getRuleForSvg = () => ({
  test: /\.svg$/,
  use: [
    {
      loader: require.resolve('@svgr/webpack'),
      options: {
        prettier: false,
        svgo: false,
        svgoConfig: { plugins: [{ removeViewBox: false }] },
        titleProp: true,
        ref: true,
      },
    },
    {
      loader: require.resolve('file-loader'),
      options: { name: 'static/media/[name].[hash].[ext]' },
    },
  ],
  issuer: { and: [/\.(ts|tsx|js|jsx|md|mdx)$/], },
});

const getBabelLoaderConfig = (isProd, shouldUseReactRefresh, cacheId) => {
  const plugins = [shouldUseReactRefresh && require.resolve('react-refresh/babel')].filter(Boolean);
  return {
    test: /\.(js|mjs|jsx|ts|tsx)$/,
    include: paths.appSrc,
    loader: require.resolve('babel-loader'),
    options: getBabelOptions(cacheId, plugins, isProd),
  };
};

const getBabelLoaderConfigForNodeModules = (cacheId, isProd) => ({
  test: /\.(js|mjs)$/,
  exclude: /@babel(?:\/|\\{1,2})runtime/,
  loader: require.resolve('babel-loader'),
  options: {
    babelrc: false,
    configFile: false,
    compact: false,
    presets: [
      [
        require.resolve('babel-preset-react-app/dependencies'),
        { helpers: true },
      ],
    ],
    cacheDirectory: true,
    cacheCompression: false,
    cacheIdentifier: cacheId,
    sourceMaps: shouldUseSourceMap,
    inputSourceMap: shouldUseSourceMap,
  },
});

/**
 * @param {any} env
 * @param {boolean} isProd
 * @return {Record<string, any>}
 */
const getDevHtmlMinifyConfig = (env, isProd) =>
  isProd
    ? {
        minify: {
          removeComments: true,
          collapseWhitespace: true,
          removeRedundantAttributes: true,
          useShortDoctype: true,
          removeEmptyAttributes: true,
          removeStyleLinkTypeAttributes: true,
          keepClosingSlash: true,
          minifyJS: true,
          minifyCSS: true,
          minifyURLs: true,
        },
      }
    : undefined;

const getHtmlPluginOptions = (env, isProd, template) =>
  Object.assign(
    {},
    {
      inject: true,
      template,
    },
    getDevHtmlMinifyConfig(env, isProd)
  );

const getWebpackPlugins = (
  env,
  isProd,
  isDev,
  shouldInlineRuntimeChunk,
  shouldUseReactRefresh,
  useTypeScript,
  swSrc,
  disableESLintPlugin,
  emitErrorsAsWarnings,
  hasJsxRuntime
) => {
  const HtmlWebpackPluginPlugin = new HtmlWebpackPlugin(
    getHtmlPluginOptions(env.raw, isProd, paths.appHtml)
  );

  const plugins = [HtmlWebpackPluginPlugin];

  if (isProd && shouldInlineRuntimeChunk) {
    plugins.push(new InlineChunkHtmlPlugin(HtmlWebpackPlugin, [/runtime-.+[.]js/]));
  }

  plugins.push(new InterpolateHtmlPlugin(HtmlWebpackPlugin, env.raw));
  plugins.push(new ModuleNotFoundPlugin(paths.appPath));
  plugins.push(new webpack.DefinePlugin(env.stringified));

  if (isDev && shouldUseReactRefresh) {
    plugins.push(
      new ReactRefreshWebpackPlugin({
        overlay: false,
      })
    );
  }

  if (isDev) {
    plugins.push(new CaseSensitivePathsPlugin());
  }

  if (isProd) {
    plugins.push(
      new MiniCssExtractPlugin({
        filename: 'static/css/[name].[contenthash:8].css',
        chunkFilename: 'static/css/[name].[contenthash:8].chunk.css',
      })
    );
  }

  plugins.push(
    new WebpackManifestPlugin({
      fileName: 'asset-manifest.json',
      publicPath: paths.publicUrlOrPath,
      generate: (seed, files, entrypoints) => {
        const manifestFiles = files.reduce((manifest, file) => {
          manifest[file.name] = file.path;
          return manifest;
        }, seed);
        const entrypointFiles = entrypoints.main.filter(
          fileName => !fileName.endsWith('.map')
        );

        return {
          files: manifestFiles,
          entrypoints: entrypointFiles,
        };
      },
    })
  );

  plugins.push(
    new webpack.IgnorePlugin({
      resourceRegExp: /^\.\/locale$/,
      contextRegExp: /moment$/,
    })
  );

  if (isProd && fs.existsSync(swSrc)) {
    plugins.push(
      new WorkboxWebpackPlugin.InjectManifest({
        swSrc,
        dontCacheBustURLsMatching: /\.[0-9a-f]{8}\./,
        exclude: [/\.map$/, /asset-manifest\.json$/, /LICENSE/],
        maximumFileSizeToCacheInBytes: 5 * 1024 * 1024,
      })
    );
  }

  if (useTypeScript) {
    plugins.push(
      new ForkTsCheckerWebpackPlugin({
        async: isDev,
        typescript: {
          typescriptPath: resolve.sync('typescript', {
            basedir: paths.appNodeModules,
          }),
          configOverwrite: {
            compilerOptions: {
              sourceMap: shouldUseSourceMap,
              skipLibCheck: true,
              inlineSourceMap: false,
              declarationMap: false,
              noEmit: true,
              incremental: true,
              tsBuildInfoFile: paths.appTsBuildInfoFile,
            },
          },
          context: paths.appPath,
          diagnosticOptions: { syntactic: true },
          mode: 'write-references',
        },
        issue: {
          include: [
            { file: '../**/src/**/*.{ts,tsx}' },
            { file: '**/src/**/*.{ts,tsx}' },
          ],
          exclude: [
            { file: '**/src/**/__tests__/**' },
            { file: '**/src/**/?(*.){spec|test}.*' },
            { file: '**/src/setupProxy.*' },
            { file: '**/src/setupTests.*' },
          ],
        },
        logger: { infrastructure: 'silent' },
      })
    );
  }

  if (!disableESLintPlugin) {
    plugins.push(
      new ESLintPlugin({
        extensions: ['js', 'mjs', 'jsx', 'ts', 'tsx'],
        formatter: require.resolve('react-dev-utils/eslintFormatter'),
        eslintPath: require.resolve('eslint'),
        failOnError: !(isDev && emitErrorsAsWarnings),
        context: paths.appSrc,
        cache: true,
        cacheLocation: path.resolve(paths.appNodeModules, '.cache/.eslintcache'),
        cwd: paths.appPath,
        resolvePluginsRelativeTo: __dirname,
        baseConfig: {
          extends: [require.resolve('eslint-config-react-app/base')],
          rules: {
            ...(!hasJsxRuntime && { 'react/react-in-jsx-scope': 'error' }),
          },
        },
      })
    );
  }

  return plugins;
};

module.exports = function (webpackEnv) {
  const isDev = isEnvDevelopment(webpackEnv);
  const isProd = isEnvProduction(webpackEnv);
  const isProfile = isEnvProductionProfile(webpackEnv, process.argv);
  const env = getClientEnvironment(paths.publicUrlOrPath.slice(0, -1));
  const shouldUseReactRefresh = env.raw.FAST_REFRESH;

  const cacheIdentifier = getCacheIdForBabel(
    isProd ? 'production' : isDev && 'development',
    [
      'babel-plugin-named-asset-import',
      'babel-preset-react-app',
      'react-dev-utils',
      'react-scripts',
    ]
  );

  const rules = [
    shouldUseSourceMap && {
      enforce: 'pre',
      exclude: /@babel(?:\/|\\{1,2})runtime/,
      test: /\.(js|mjs|jsx|ts|tsx|css)$/,
      loader: require.resolve('source-map-loader'),
    },
    {
      oneOf: [
        getRuleForAvif(),
        getRuleForImages(),
        getRuleForSvg(),
        getBabelLoaderConfig(isProd, shouldUseReactRefresh, cacheIdentifier),
        getBabelLoaderConfigForNodeModules(cacheIdentifier, isProd),
        {
          test: cssRegex,
          exclude: cssModuleRegex,
          use: getStyleLoaders({
            importLoaders: 1,
            sourceMap: shouldUseSourceMap,
            modules: { mode: 'icss' },
          }),
          sideEffects: true,
        },
        {
          test: cssModuleRegex,
          use: getStyleLoaders({
            importLoaders: 1,
            sourceMap: shouldUseSourceMap,
            modules: {
              mode: 'local',
              getLocalIdent: getCSSModuleLocalIdent,
            },
          }),
        },
        {
          test: sassRegex,
          exclude: sassModuleRegex,
          use: getStyleLoaders(
            {
              importLoaders: 3,
              sourceMap: shouldUseSourceMap,
              modules: { mode: 'icss' },
            },
            'sass-loader'
          ),
          sideEffects: true,
        },
        {
          test: sassModuleRegex,
          use: getStyleLoaders(
            {
              importLoaders: 3,
              sourceMap: shouldUseSourceMap,
              modules: {
                mode: 'local',
                getLocalIdent: getCSSModuleLocalIdent,
              },
            },
            'sass-loader'
          ),
        },
        {
          exclude: [/^$/, /\.(js|mjs|jsx|ts|tsx)$/, /\.html$/, /\.json$/],
          type: 'asset/resource',
        },
      ],
    },
  ].filter(Boolean);

  return {
    target: ['browserslist'],
    stats: 'errors-warnings',
    mode: isProd ? 'production' : isDev && 'development',
    bail: isProd,
    devtool: isProd
      ? shouldUseSourceMap
        ? 'source-map'
        : false
      : isDev && 'cheap-module-source-map',
    entry: paths.appIndexJs,
    output: {
      path: paths.appBuild,
      pathinfo: isDev,
      filename: isProd
        ? 'static/js/[name].[contenthash:8].js'
        : isDev && 'static/js/bundle.js',
      chunkFilename: isProd
        ? 'static/js/[name].[contenthash:8].chunk.js'
        : isDev && 'static/js/[name].chunk.js',
      assetModuleFilename: 'static/media/[name].[hash][ext]',
      publicPath: paths.publicUrlOrPath,
      devtoolModuleFilenameTemplate: isProd
        ? info =>
            path
              .relative(paths.appSrc, info.absoluteResourcePath)
              .replace(/\\/g, '/')
        : isDev &&
          (info =>
            path.resolve(info.absoluteResourcePath).replace(/\\/g, '/')),
    },
    cache: {
      type: 'filesystem',
      version: createEnvironmentHash(env.raw),
      cacheDirectory: paths.appWebpackCache,
      store: 'pack',
      buildDependencies: {
        defaultWebpack: ['webpack/lib/'],
        config: [__filename],
        tsconfig: [paths.appTsConfig, paths.appJsConfig].filter(f =>
          fs.existsSync(f)
        ),
      },
    },
    infrastructureLogging: {
      level: 'none',
    },
    optimization: {
      minimize: isProd,
      minimizer: getOptimizationMinimizer(isProd, isProfile),
    },
    resolve: {
      modules: ['node_modules', paths.appNodeModules].concat(
        modules.additionalModulePaths || []
      ),
      extensions: paths.moduleFileExtensions
        .map(ext => `.${ext}`)
        .filter(ext => useTypeScript || !ext.includes('ts')),
      alias: getAliasConfig(isProfile, isProd),
