								const expectedNames = expectedNamesList.shift();
								const variables =
									sourceCode.getDeclaredVariables(node);

								assert(Array.isArray(expectedNames));
								assert(Array.isArray(variables));
								assert.strictEqual(
									expectedNames.length,
									variables.length,
